import assert from 'node:assert/strict';
import { runToolCall } from '@earendil-works/pi-agent-core';
import { obj, str } from '@earendil-works/pi-schema';
let executions = 0;
const hooks = [];
const tool = {
  name: 'echo', label: 'Echo', description: 'Return a string',
  parameters: obj({ value: str() }),
  async execute(_id, args) {
    executions++;
    return { content: [{ type: 'text', text: args.value }], details: {} };
  },
};
const usage = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0,
  totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } };
const options = {
  tools: [tool], context: { messages: [] },
  assistantMessage: { role: 'assistant', content: [], api: 'faux',
    provider: 'faux', model: 'faux-1', usage, stopReason: 'stop', timestamp: 0 },
  beforeToolCall: async ({ toolCall, args }) => {
    hooks.push(`before:${toolCall.id}`);
    if (args.value === 'blocked') return { block: true, reason: 'blocked by lab' };
  },
  afterToolCall: async ({ toolCall }) => { hooks.push(`after:${toolCall.id}`); },
};
const results = [];
for (const [id, name, args] of [
  ['ok', 'echo', { value: 'ok' }],
  ['invalid', 'echo', { value: { nested: true } }],
  ['blocked', 'echo', { value: 'blocked' }],
  ['missing', 'missing', {}],
]) results.push(await runToolCall({ type: 'toolCall', id, name, arguments: args }, options));
assert.deepEqual(results.map(x => x.isError), [false, true, true, true]);
assert.equal(executions, 1);
assert.deepEqual(hooks, ['before:ok', 'after:ok', 'before:blocked']);
console.log(JSON.stringify({ errors: results.map(x => x.isError), executions, hooks }));

import assert from 'node:assert/strict';
import { isRetryableAssistantError, retryAssistantCall, retryDelayMs } from '@earendil-works/pi-ai';
const usage = { input: 0, output: 0, cacheRead: 0, cacheWrite: 0,
  totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } };
const message = (stopReason, errorMessage) => ({ role: 'assistant', content: [],
  api: 'faux', provider: 'faux', model: 'faux-1', usage, stopReason,
  ...(errorMessage ? { errorMessage } : {}), timestamp: 0 });
const policy = { enabled: true, maxRetries: 2, baseDelayMs: 0 };
let transientCalls = 0;
const result = await retryAssistantCall(async () => {
  transientCalls++;
  return transientCalls === 1 ? message('error', '503 service unavailable') : message('stop');
}, policy, undefined);
let quotaCalls = 0;
await retryAssistantCall(async () => {
  quotaCalls++;
  return message('error', '429 insufficient_quota');
}, policy, undefined);
let abortedCalls = 0;
await retryAssistantCall(async () => {
  abortedCalls++;
  return message('aborted');
}, policy, undefined);
assert.equal(isRetryableAssistantError(message('error', '429 insufficient_quota')), false);
assert.equal(result.stopReason, 'stop');
assert.deepEqual([transientCalls, quotaCalls, abortedCalls], [2, 1, 1]);
assert.equal(retryDelayMs({ baseDelayMs: 1000, maxAgentDelayMs: 2500 }, 5), 2500);
console.log(JSON.stringify({ transientCalls, quotaCalls, abortedCalls, cappedDelayMs: 2500 }));

import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
const cli = join(dirname(fileURLToPath(import.meta.resolve('@earendil-works/pi-coding-agent'))), 'cli.js');
const work = await mkdtemp(join(tmpdir(), 'pi-rpc-inspect-'));
const child = spawn(process.execPath, [cli, '--mode', 'rpc', '--no-session',
  '--no-extensions', '--no-skills', '--no-prompt-templates', '--no-themes', '--no-context-files'],
  { cwd: work, env: { PATH: process.env.PATH ?? '', TERM: 'dumb', NO_COLOR: '1',
      PI_CODING_AGENT_DIR: join(work, 'agent') },
    stdio: ['pipe', 'pipe', 'inherit'] });
let buffer = '';
const waiting = new Map();
child.stdout.setEncoding('utf8');
child.stdout.on('data', chunk => {
  buffer += chunk;
  let end;
  while ((end = buffer.indexOf('\n')) >= 0) {
    const line = buffer.slice(0, end).replace(/\r$/, '');
    buffer = buffer.slice(end + 1);
    if (!line) continue;
    const record = JSON.parse(line);
    if (record.type === 'response' && waiting.has(record.id)) {
      const { resolve, timer } = waiting.get(record.id);
      clearTimeout(timer); waiting.delete(record.id); resolve(record);
    }
  }
});
function ask(type) {
  const id = `lab-${type}`;
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => { waiting.delete(id); reject(new Error(`Timeout: ${id}`)); }, 30000);
    waiting.set(id, { resolve, timer });
    child.stdin.write(JSON.stringify({ id, type }) + '\n');
  });
}
try {
  for (const type of ['get_state', 'get_session_stats', 'get_messages']) {
    const response = await ask(type);
    assert.equal(response.id, `lab-${type}`);
    assert.equal(response.command, type);
    assert.equal(response.success, true, JSON.stringify(response));
    console.log(JSON.stringify({ id: response.id, command: type, success: response.success }));
  }
  const exited = once(child, 'exit');
  child.stdin.end();
  const [status] = await exited;
  assert.equal(status, 0);
} finally {
  if (child.exitCode === null) child.kill();
}

import assert from 'node:assert/strict';
import { SessionManager } from '@earendil-works/pi-coding-agent';
const manager = SessionManager.inMemory();
const original = 'RAW_CONTEXT_SENTINEL';
const id = manager.appendMessage({ role: 'user', content: original, timestamp: 0 });
manager.appendContextEdit(id, { content: 'short replacement' });
assert.equal(manager.getEntry(id).message.content, original);
assert.equal(manager.buildSessionContext().messages[0].content, 'short replacement');
manager.appendContextEdit(id, null);
assert.equal(manager.buildSessionContext().messages.length, 0);
assert.equal(manager.getEntry(id).message.content, original);
manager.branch(id);
assert.equal(manager.buildSessionContext().messages[0].content, original);
assert.equal(manager.getEntries().filter(e => e.type === 'context_edit').length, 2);
console.log(JSON.stringify({ rawPreserved: true, replacementApplied: true,
  omissionApplied: true, beforeEditRestored: true }));

import assert from 'node:assert/strict';
import { SessionManager } from '@earendil-works/pi-coding-agent';
const user = content => ({ role: 'user', content, timestamp: 0 });
const compacted = SessionManager.inMemory();
const oldId = compacted.appendMessage(user('OLD_RAW_SENTINEL'));
const keptId = compacted.appendMessage(user('continue with the query test'));
const compactId = compacted.appendCompaction('Earlier work chose SQLite.', keptId, 1234);
const projected = JSON.stringify(compacted.buildSessionContext().messages);
assert.equal(compacted.getEntry(oldId).message.content, 'OLD_RAW_SENTINEL');
assert.equal(compacted.getEntry(compactId).firstKeptEntryId, keptId);
assert.ok(projected.includes('Earlier work chose SQLite.'));
assert.ok(projected.includes('continue with the query test'));
assert.ok(!projected.includes('OLD_RAW_SENTINEL'));
const branched = SessionManager.inMemory();
const common = branched.appendMessage(user('shared goal'));
const oldLeaf = branched.appendMessage(user('LEFT_RAW_SENTINEL'));
const summaryId = branched.branchWithSummary(common, 'Approach A was explored.', undefined, true);
const summary = branched.getEntry(summaryId);
assert.equal(summary.parentId, common);
assert.equal(summary.fromId, oldLeaf);
assert.equal(branched.getEntry(oldLeaf).message.content, 'LEFT_RAW_SENTINEL');
const newContext = JSON.stringify(branched.buildSessionContext().messages);
assert.ok(newContext.includes('Approach A was explored.'));
assert.ok(!newContext.includes('LEFT_RAW_SENTINEL'));
console.log(JSON.stringify({ compactionRebuilt: true, branchSummaryLinked: true, rawHistoryPreserved: true }));
